import asyncio
from collections import defaultdict, deque

class DependencyGraph:
    def __init__(self):
        self.adj = defaultdict(list)
        self.in_degree = defaultdict(int)
        self.nodes = set()

    def add_dependency(self, u: str, v: str):
        self.adj[u].append(v)
        self.in_degree[v] += 1
        self.nodes.add(u)
        self.nodes.add(v)

    def resolve_order(self) -> list[str]:
        queue = deque([n for n in self.nodes if self.in_degree[n] == 0])
        order = []
        while queue:
            curr = queue.popleft()
            order.append(curr)
            for neighbor in self.adj[curr]:
                self.in_degree[neighbor] -= 1
                if self.in_degree[neighbor] == 0:
                    queue.append(neighbor)
        if len(order) != len(self.nodes):
            raise ValueError('Cyclic dependency detected in graph')
        return order

import time
import random
from typing import Callable, Any

def retry_with_backoff(
    func: Callable[..., Any],
    max_retries: int = 5,
    base_delay: float = 0.1,
    max_delay: float = 2.0,
) -> Any:
    for attempt in range(max_retries):
        try:
            return func()
        except Exception as exc:
            if attempt == max_retries - 1:
                raise exc
            delay = min(max_delay, base_delay * (2 ** attempt))
            jitter = random.uniform(0, delay * 0.1)
            time.sleep(delay + jitter)

export type ParseResult<T> = { success: true; data: T } | { success: false; errors: string[] };

export interface Schema<T> {
  parse(value: unknown): ParseResult<T>;
}

export const stringSchema: Schema<string> = {
  parse(val: unknown) {
    return typeof val === 'string'
      ? { success: true, data: val }
      : { success: false, errors: ['Expected string, received ' + typeof val] };
  }
};

export const numberSchema: Schema<number> = {
  parse(val: unknown) {
    return typeof val === 'number' && !Number.isNaN(val)
      ? { success: true, data: val }
      : { success: false, errors: ['Expected valid number'] };
  }
};

import kotlinx.coroutines.*
import kotlinx.coroutines.channels.Channel

suspend fun <T> drainChannelSafely(channel: Channel<T>, onElement: suspend (T) -> Unit) {
    coroutineScope {
        try {
            for (item in channel) {
                ensureActive()
                onElement(item)
            }
        } catch (e: CancellationException) {
            // Safe cleanup of pending resources
            channel.cancel()
            throw e
        }
    }
}

class Node:
    def __init__(self, key=0, value=0):
        self.key, self.value = key, value
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.cache = {}
        self.head, self.tail = Node(), Node()
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, node: Node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def _add(self, node: Node):
        node.prev = self.head
        node.next = self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key: int) -> int:
        if key in self.cache:
            node = self.cache[key]
            self._remove(node)
            self._add(node)
            return node.value
        return -1

    def put(self, key: int, value: int):
        if key in self.cache:
            self._remove(self.cache[key])
        node = Node(key, value)
        self._add(node)
        self.cache[key] = node
        if len(self.cache) > self.cap:
            lru = self.tail.prev
            self._remove(lru)
            del self.cache[lru.key]
